// Puerta de prueba: el hilo llega ya armado desde src/probador.py, con la
// fecha en que entró el correo para que «el jueves» se entienda como entonces.
// Deja lo mismo que el «Armar el hilo» del recorrido del buzón, con el mismo
// nombre, para que la lectura use las mismas instrucciones sin tocarlas.
const { hilo, fecha_hoy } = $json.body;
return [{ json: {
  hilo,
  fecha_hoy: fecha_hoy || new Date().toISOString().slice(0, 10),
  duraciones: "40, 60, 90",
  texto_hilo: hilo.mensajes.map(m => `De: ${m.de}\n${m.texto}`).join("\n\n---\n\n"),
}}];

// Junta el hilo con lo que entendió el modelo y arma lo que come nuestro código.
const crudo = $json.text ?? $json.response?.text ?? JSON.stringify($json);
const limpio = String(crudo).replace(/^```(json)?/i, "").replace(/```$/, "").trim();
let lectura;
try { lectura = JSON.parse(limpio); }
catch (e) { throw new Error("El modelo no devolvió un JSON válido: " + limpio.slice(0, 300)); }
const hilo = $('Armar el hilo').first().json.hilo;
return [{ json: { entrada: { pedido: { origen: "buzon", hilo, lectura } } } }];
